def first_extraction_version(apps, schema_editor):
    """The configuration the worker used so far (LLM_MODEL, LLM_STRUCTURED_OUTPUT,
    EXTRACTION_FEW_SHOT and the few-shot files) goes into the extraction version in use; a
    database without one gets it as version 1."""
    Version = apps.get_model("mlops", "ModelVersion")
    count = int(os.environ.get("EXTRACTION_FEW_SHOT") or 1)
    config = {
        "llm_model": os.environ.get("LLM_MODEL") or "",
        "prompt_version": PROMPT_VERSION,
        "structured_output": (os.environ.get("LLM_STRUCTURED_OUTPUT") or "true").strip().lower()
        not in FALSE_VALUES,
        "few_shot_examples": json.loads(FEW_SHOT.read_text(encoding="utf-8"))[:count],
    }
    in_use = Version.objects.filter(module="ext", status="production").order_by("-id").first()
    if in_use is not None:
        Version.objects.filter(pk=in_use.pk).update(**config)
        return
    version = Version.objects.create(
        module="ext",
        name="extraction",
        version="1",
        status="production",
        reason="Konfiguracja ekstrakcji sprzed wersjonowania (pliki i zmienne środowiskowe)",
        **config,
    )
    apps.get_model("mlops", "ModuleUsagePeriod").objects.create(
        module_version=version, started_at=timezone.now()
    )


